import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var objects = [
    { title: 'MAZ 5440', subtitle: 'AB 1234-7 · Движется', state: 'moving', course: 135, value: '62 км/ч', valueMeta: 'Иванов П.' },
    { title: 'Volvo FH16', subtitle: 'AC 8871-2 · Стоянка', state: 'parked', value: '0 км/ч' },
    { title: 'Служебный автомобиль северо-западного подразделения', subtitle: 'AE 3401-7 · Нет связи', state: 'offline' }
];
function ListExample(props) {
    var canView = props.mode !== 'select', canSelect = props.mode !== 'view', active = React.useState(0), selected = React.useState([1]), message = React.useState(''), checkSide = React.useState('left');
    return <div className={"demo-stack"}>
    {canSelect ? <div>
    <S.DsButton tone={'secondary'} size={'sm'} onClick={function () { checkSide[1](checkSide[0] === 'left' ? 'right' : 'left'); }}>
    {checkSide[0] === 'left' ? 'Чекбоксы справа' : 'Чекбоксы слева'}
    </S.DsButton>
    </div> : null}
    <div className={'list'}>
    {objects.map(function (object, i) {
            var checkbox = canSelect ? <S.DsCheckbox key={'check'} state={selected[0].includes(i) ? 'checked' : 'unchecked'} ariaLabel={'Выбрать: ' + object.title} onChange={function (next) { selected[1](next === 'checked' ? selected[0].concat(i) : selected[0].filter(function (id) { return id !== i; })); }}/> : null, row = <S.DsListRow {...Object.assign({}, object, { key: 'row', active: canView && active[0] === i, selected: canSelect && selected[0].includes(i), onClick: canView ? function () { active[1](i); } : undefined,
                badge: i === 1 ? <S.DsLozenge tone={'info'} size={'sm'}>
            {'Pro'}
            </S.DsLozenge> : undefined,
                actionsWidth: canView ? 32 : undefined, actions: canView && i !== 2 ? <S.DsIconButton icon={'info'} label={'Сведения: ' + object.title} size={'sm'} onClick={function () { message[1]('Сведения об объекте ' + object.title); }}/> : undefined })}/>;
            return <div className={'choice'} key={i}>
        {checkSide[0] === 'left' ? [checkbox, row] : [row, checkbox]}
        </div>;
        })}
    </div>
    <p className={'cap'} role={'status'}>
    {(canView ? 'Открыт: ' + objects[active[0]].title + '. ' : '') + (canSelect ? 'Выбрано объектов: ' + selected[0].length + '.' : '')}
    </p>
    {canView ? <p className={'cap'} role={'status'}>
    {message[0] || (canSelect ? 'Строка открывает объект, чекбокс меняет выбор.' : 'Нажмите строку или кнопку сведений.')}
    </p> : null}
    </div>;
}
function App() {
    return <div className="dslistrow-example">
    <style>{exampleStyles}</style>
    <ListExample mode={'view'} title={'Просмотр и действия'}/>
    </div>;
}

const exampleStyles = ".dslistrow-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dslistrow-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dslistrow-example p{margin:0}\n.dslistrow-example .list{display:flex;flex-direction:column;gap:2px;max-width:560px;min-width:0}\n.dslistrow-example .choice{display:flex;align-items:center;gap:var(--ds-gap-sm);min-width:0}\n.dslistrow-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

